package stock

import ovid/io

// TestGoalTable adds 100 names and checks every count survived the table
// growing, and that a name is not mistaken for its prefix.
func TestGoalTable(io *ovid/io.Cap) i64 {
  var t *Table = NewTable(io)
  var buf i64 = ovid/io.Alloc(io, 400)
  var i i64 = 0
  while i < 100 {
    store8(buf + i * 4, 110)
    store8(buf + i * 4 + 1, 48 + i / 10)
    store8(buf + i * 4 + 2, 48 + i % 10)
    var k i64 = Index(io, t, buf + i * 4, 3)
    store64(t.counts + k * 8, load64(t.counts + k * 8) + i + 1)
    i = i + 1
  }
  if t.len != 100 {
    return 1
  }
  i = 0
  while i < 100 {
    if load64(t.counts + i * 8) != i + 1 || Index(io, t, buf + i * 4, 3) != i {
      return 2
    }
    i = i + 1
  }
  if Index(io, t, buf, 2) != 100 || Index(io, t, buf, 4) != 101 {
    return 3
  }
  if Same(buf, 2, buf, 3) || !Same(buf, 3, buf, 3) || Same(strptr("ab"), 2, strptr("ac"), 2) {
    return 4
  }
  return 0
}

// TestGoalLoad checks the line rules: the number of the first bad line,
// a last line without a newline, and empty lines.
func TestGoalLoad(io *ovid/io.Cap) i64 {
  var t *Table = NewTable(io)
  if Load(io, t, strptr("a 1\n\nb 2\nc"), strlen("a 1\n\nb 2\nc")) != 4 {
    return 1
  }
  t = NewTable(io)
  if Load(io, t, strptr("a 1\n\nb 23"), strlen("a 1\n\nb 23")) != 0 || t.len != 2 || load64(t.counts + 8) != 23 {
    return 2
  }
  t = NewTable(io)
  if Load(io, t, strptr("\n"), 1) != 0 || t.len != 0 || Load(io, t, strptr(""), 0) != 0 {
    return 3
  }
  return 0
}
